func testTituloToManySetOpTitRetornoBancarioTitulos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Titulo
	var b, c, d, e RetornoBancarioTitulo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, tituloDBTypes, false, strmangle.SetComplement(tituloPrimaryKeyColumns, tituloColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*RetornoBancarioTitulo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, retornoBancarioTituloDBTypes, false, strmangle.SetComplement(retornoBancarioTituloPrimaryKeyColumns, retornoBancarioTituloColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetTitRetornoBancarioTitulos(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.TitRetornoBancarioTitulos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetTitRetornoBancarioTitulos(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.TitRetornoBancarioTitulos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.TitID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.TitID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.TitID, d.TitID) {
		t.Error("foreign key was wrong value", a.TitID, d.TitID)
	}
	if !queries.Equal(a.TitID, e.TitID) {
		t.Error("foreign key was wrong value", a.TitID, e.TitID)
	}

	if b.R.Tit != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Tit != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Tit != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Tit != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.TitRetornoBancarioTitulos[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.TitRetornoBancarioTitulos[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

func testTituloToManyRemoveOpTitRetornoBancarioTitulos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Titulo
	var b, c, d, e RetornoBancarioTitulo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, tituloDBTypes, false, strmangle.SetComplement(tituloPrimaryKeyColumns, tituloColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*RetornoBancarioTitulo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, retornoBancarioTituloDBTypes, false, strmangle.SetComplement(retornoBancarioTituloPrimaryKeyColumns, retornoBancarioTituloColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddTitRetornoBancarioTitulos(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.TitRetornoBancarioTitulos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveTitRetornoBancarioTitulos(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.TitRetornoBancarioTitulos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.TitID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.TitID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Tit != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Tit != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Tit != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Tit != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.TitRetornoBancarioTitulos) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.TitRetornoBancarioTitulos[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.TitRetornoBancarioTitulos[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

