func testTituloToOneTituloUsingTitTit(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Titulo
	var foreign Titulo

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, tituloDBTypes, true, tituloColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Titulo struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, tituloDBTypes, false, tituloColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Titulo struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.TitTitID, foreign.TitID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.TitTit().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.TitID, foreign.TitID) {
		t.Errorf("want: %v, got %v", foreign.TitID, check.TitID)
	}

	ranAfterSelectHook := false
	AddTituloHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Titulo) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := TituloSlice{&local}
	if err = local.L.LoadTitTit(ctx, tx, false, (*[]*Titulo)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.TitTit == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.TitTit = nil
	if err = local.L.LoadTitTit(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.TitTit == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

